","/**
 * responseProvider — Keyword-matched response data for the Operations Copilot.
 * Provides structured intelligence responses with sections, metrics, and actions.
 */

export interface MetricItem {
 label: string;
 value: string;
 trend?: "up" | "down" | "neutral";
}

export interface ResponseSection {
 title: string;
 severity?: "critical" | "warning" | "info" | "positive";
 badge?: string;
 bullets?: string[];
 metrics?: MetricItem[];
}

export interface RecommendedAction {
 title: string;
 description: string;
 priority: "high" | "medium" | "low";
}

export interface CopilotResponse {
 summary: string;
 sections: ResponseSection[];
 recommendedAction: RecommendedAction;
 timestamp: string;
}

function getTimestamp(): string {
 return new Date().toLocaleString("en-US", {
 hour: "numeric",
 minute: "2-digit",
 hour12: true,
 month: "short",
 day: "numeric",
 });
}

function matchResponse(question: string): CopilotResponse {
 const q = question.toLowerCase();

 // Store 104 PulseScore
 if (q.includes("store 104") || q.includes("pulsescore") || q.includes("pulse score")) {
 return {
 summary:
 "Store 104's PulseScore dropped from 87 to 62 over the past 48 hours due to a compounding set of operational failures: refrigeration unit malfunction, three delivery partner no-shows, and a surge in customer complaints about missing items from dark store fulfillment.",
 sections: [
 {
