 ],
 },
 {
 title: "Impact Metrics",
 severity: "warning",
 metrics: [
 { label: "PulseScore", value: "62/100", trend: "down" },
 { label: "Order Fulfillment", value: "74%", trend: "down" },
 { label: "Customer Complaints", value: "12", trend: "up" },
 { label: "Revenue Impact", value: "-₹18,400", trend: "down" },
 ],
 },
 ],
 recommendedAction: {
 title: "Dispatch maintenance crew + activate backup delivery partner",
 description:
 "Schedule emergency refrigeration repair (est. 2h fix), activate backup delivery partner pool for Store 104, and issue proactive customer credits for affected orders.",
 priority: "high",
 },
 timestamp: getTimestamp(),
 };
 }

 // Stores needing attention
 if (q.includes("immediate attention") || q.includes("need attention") || q.includes("stores need")) {
 return {
 summary:
 "Three stores require immediate intervention based on real-time PulseScore monitoring and anomaly detection. Store 104 is critical, Store 87 is degrading, and Store 23 has an emerging equipment issue.",
 sections: [
 {
 title: "Critical — Store 104 (Koramangala)",
