 priority: "high",
 },
 timestamp: getTimestamp(),
 };
 }

 // Today's operations summary
 if (q.includes("summarize") || q.includes("today") || q.includes("summary") || q.includes("operations overview")) {
 return {
 summary:
 "Today's operations across 52 monitored stores show overall healthy performance with a fleet-wide PulseScore of 83/100. Three stores flagged for attention, delivery SLA compliance at 91%, and total revenue tracking 4% above daily target.",
 sections: [
 {
 title: "Fleet Performance",
 severity: "positive",
 metrics: [
 { label: "Avg PulseScore", value: "83/100", trend: "neutral" },
 { label: "Orders Fulfilled", value: "4,287", trend: "up" },
 { label: "Delivery SLA", value: "91%", trend: "neutral" },
 { label: "Revenue", value: "₹12.4L", trend: "up" },
 ],
 },
 {
 title: "Alerts & Incidents",
 severity: "warning",
 badge: "7 Active",
 bullets: [
 "3 stores below PulseScore threshold (104, 87, 23)",
 "2 equipment maintenance tickets open",
 "1 delivery partner suspension pending review",
 "1 fraud alert under investigation",
 ],
 },
 {
 title: "Staffing",
 severity: "info",
 bullets: [
 "96% shift coverage across all stores",
 "4 sick-leave gaps (2 covered by on-call, 2 uncovered at Store 87)",
 "Evening shift fully staffed",
 ],
 },
 ],
 recommendedAction: {
 title: "Address Store 104 critical + fill Store 87 staffing gaps",
 description:
 "Primary focus: resolve Store 104 refrigeration issue and backfill Store 87's missing staff. All other stores performing within acceptable parameters.",
 priority: "medium",
 },
 timestamp: getTimestamp(),
 };
 }

 // Equipment failures
 if (q.includes("equipment") || q.includes("failure") || q.includes("maintenance") || q.includes("hardware")) {
 return {
 summary:
 "Currently tracking 5 active equipment issues across the fleet: 2 critical (affecting operations), 2 moderate (degraded performance), and 1 preventive maintenance item. Total estimated repair cost: ₹1.2L.",
 sections: [
 {
