 severity: "warning",
 badge: "2 Moderate",
 bullets: [
 "Store 87 — Conveyor belt speed reduced 40% (bearing wear). Scheduled replacement tomorrow.",
 "Store 12 — HVAC intermittent. Staff comfort affected, no product impact.",
 ],
 },
 {
 title: "Preventive Maintenance",
 severity: "info",
 badge: "1 Scheduled",
 bullets: [
 "Store 23 — Freezer #2 showing early temperature drift. Recommend proactive service within 4h.",
 ],
 },
 ],
 recommendedAction: {
 title: "Dispatch maintenance to Store 104 and schedule Store 23",
 description:
 "Priority 1: Emergency refrigeration repair at Store 104. Priority 2: Preventive freezer service at Store 23 before temperature breach. Store 45 POS issue can wait for next-day service call.",
 priority: "high",
 },
 timestamp: getTimestamp(),
 };
 }

 // Delivery partner incidents
 if (q.includes("delivery partner") || q.includes("delivery incidents") || q.includes("partner incidents") || q.includes("riders")) {
 return {
 summary:
 "14 delivery partner incidents logged in the past 24 hours: 6 no-shows, 4 late pickups (>10 min SLA breach), 3 customer complaints about handling, and 1 suspected fraud case. Partner reliability index at 88% (target: 95%).",
 sections: [
 {
