 "Average delay: 14 min beyond SLA window",
 "Concentrated in South Bangalore zone (3 of 4)",
 "Contributing factor: traffic incident on Outer Ring Road",
 ],
 },
 {
 title: "Fraud Alert",
 severity: "critical",
 badge: "1 Case",
 bullets: [
 "Partner ID #DP-4421: GPS spoofing detected on 2 deliveries",
 "Account suspended pending investigation",
 "Affected customers refunded automatically",
 ],
 },
 ],
 recommendedAction: {
 title: "Suspend QuickRide pool for Store 104, escalate fraud case",
 description:
 "Temporarily remove QuickRide from Store 104's partner rotation and activate backup pool. Escalate Partner #DP-4421 fraud case to investigations team with GPS evidence.",
 priority: "high",
 },
 timestamp: getTimestamp(),
 };
 }

 // Refund statistics
 if (q.includes("refund") || q.includes("returns") || q.includes("refund statistics")) {
 return {
 summary:
 "Refund volume is 23% above weekly average, primarily driven by missing item complaints at Store 104 and delivery quality issues. Total refunds processed today: ₹47,200 across 34 cases. Auto-refund rate: 76%.",
 sections: [
 {
 title: "Refund Breakdown",
 severity: "warning",
 metrics: [
 { label: "Total Today", value: "₹47,200", trend: "up" },
 { label: "Cases", value: "34", trend: "up" },
 { label: "Auto-Approved", value: "76%", trend: "neutral" },
 { label: "Avg Amount", value: "₹1,388", trend: "up" },
 ],
 },
 {
 title: "Top Refund Reasons",
 severity: "info",
 bullets: [
 "Missing items (41%) — concentrated at Store 104",
 "Damaged in transit (24%) — delivery handling issues",
 "Wrong product sent (18%) — packing errors at Store 87",
 "Late delivery beyond window (12%) — SLA breaches",
 "Other (5%) — customer change of mind",
 ],
 },
 ],
 recommendedAction: {
 title: "Investigate Store 104 missing items pattern + audit packing at Store 87",
 description:
 "The spike correlates with Store 104's operational issues. Fixing the root cause (refrigeration + delivery) should reduce refunds by ~35%. Also audit Store 87's packing process for wrong-item errors.",
 priority: "medium",
 },
 timestamp: getTimestamp(),
 };
 }

 // Fraud alerts
 if (q.includes("fraud") || q.includes("suspicious") || q.includes("fraud alert")) {
 return {
 summary:
 "3 active fraud alerts in the system: 1 confirmed delivery partner GPS spoofing, 1 suspected inventory shrinkage pattern at Store 19, and 1 unusual refund pattern flagged by the ML model. Total estimated exposure: ₹2.1L.",
 sections: [
 {
 title: "Confirmed — GPS Spoofing",
 severity: "critical",
 badge: "Confirmed",
 bullets: [
 "Partner #DP-4421 flagged for GPS coordinate manipulation",
 "2 deliveries show impossible location jumps (3km in 30 sec)",
 "Account suspended, 2 affected customers auto-refunded",
 ],
 },
 {
 title: "Suspected — Inventory Shrinkage",
 severity: "warning",
 badge: "Investigating",
 bullets: [
 "Store 19: 4.2% inventory variance (threshold: 1.5%)",
 "Pattern: high-value items (electronics accessories) disproportionately affected",
 "Correlates with specific shift window (18:00-22:00)",
 ],
 },
 {
 title: "Flagged — Refund Pattern Anomaly",
 severity: "info",
 badge: "ML Flagged",
 bullets: [
 "Customer cluster (5 accounts) filing similar refund claims within 48h",
 "All claims cite 'missing items' for same product categories",
 "Geo-location overlap suggests coordinated activity",
 ],
 },
 ],
 recommendedAction: {
 title: "Escalate GPS fraud + deploy covert audit at Store 19",
 description:
 "Forward Partner #DP-4421 evidence to legal/investigations. Deploy inventory audit team to Store 19 during evening shift. For the refund cluster, enable enhanced verification for flagged accounts.",
 priority: "high",
 },
 timestamp: getTimestamp(),
 };
 }

 // Operations focus / priorities
 if (q.includes("focus") || q.includes("priorities") || q.includes("what should")) {
 return {
 summary:
 "Based on current operational data, today's top priorities should be: (1) Resolve Store 104's compounding failures, (2) Backfill Store 87 staffing gaps before evening rush, and (3) Close the delivery partner fraud investigation. These three items account for 78% of active risk exposure.",
 sections: [
 {
 title: "Priority 1 — Store 104 Recovery",
 severity: "critical",
 badge: "Urgent",
 bullets: [
 "Dispatch refrigeration repair crew (est. 2h)",
 "Activate backup delivery partner pool",
 "Issue proactive credits to 12 affected customers",
 "Expected PulseScore recovery: +15 pts within 6h of resolution",
 ],
 },
 {
 title: "Priority 2 — Store 87 Staffing",
 severity: "warning",
 badge: "Before 17:00",
 bullets: [
 "2 uncovered positions for evening shift",
 "Activate on-call staff or cross-deploy from Store 56 (overstaffed today)",
 "Clear order backlog before peak hours (17:00-21:00)",
 ],
 },
 {
 title: "Priority 3 — Fraud Resolution",
 severity: "info",
 badge: "Today",
 bullets: [
 "Complete Partner #DP-4421 investigation and file report",
 "Decide on Store 19 audit timing",
 "Review ML-flagged refund cluster and set verification rules",
 ],
 },
 ],
 recommendedAction: {
 title: "Start with Store 104 dispatch, then parallel-track the rest",
 description:
 "The refrigeration repair has the longest lead time — dispatch immediately. While waiting, handle staffing calls for Store 87 and fraud paperwork. This sequence maximizes resolution speed across all three priorities.",
 priority: "high",
 },
 timestamp: getTimestamp(),
 };
 }

 // Default / catch-all
 return {
 summary:
 `I've analyzed your query: "${question}". Based on current operational data across 52 monitored stores, here's a contextual summary of relevant insights and recommended actions.`,
 sections: [
 {
 title: "Current Fleet Status",
 severity: "info",
 metrics: [
 { label: "Active Stores", value: "52", trend: "neutral" },
 { label: "Avg PulseScore", value: "83/100", trend: "neutral" },
 { label: "Open Alerts", value: "7", trend: "neutral" },
 { label: "Delivery SLA", value: "91%", trend: "neutral" },
 ],
 },
 {
 title: "Key Observations",
 severity: "info",
 bullets: [
 "3 stores below performance threshold (104, 87, 23)",
 "Delivery partner reliability at 88% (below 95% target)",
 "Equipment maintenance: 2 critical, 2 moderate, 1 preventive",
 "Refund volume trending 23% above weekly average",
 ],
 },
 ],
 recommendedAction: {
 title: "Ask me something more specific for deeper analysis",
 description:
 "Try asking about specific stores, equipment status, delivery partners, refund trends, fraud alerts, or today's operational priorities for detailed intelligence.",
 priority: "low",
 },
 timestamp: getTimestamp(),
 };
}

/**
 * Get a copilot response for a given question.
 * Reduced delay (~200ms) since streaming provides the perceptual delay.
 */
export async function getResponse(question: string): Promise<CopilotResponse> {
 // ~3 second thinking delay while typing indicator shows
 await new Promise((resolve) => setTimeout(resolve, 2800 + Math.random() * 400));
 return matchResponse(question);
}
