","/* ===== Operations Copilot — Dark Theme Styles ===== */

* {
 margin: 0;
 padding: 0;
 box-sizing: border-box;
}

.copilot-page {
 display: flex;
 flex-direction: column;
 height: 100vh;
 background: #0a0e14;
 color: #e4e8f0;
 font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, sans-serif;
}

/* --- Header --- */
.copilot-header {
 display: flex;
 align-items: center;
 justify-content: space-between;
 padding: 16px 24px;
 background: rgba(15, 20, 30, 0.95);
 border-bottom: 1px solid rgba(255, 255, 255, 0.06);
 backdrop-filter: blur(12px);
 flex-shrink: 0;
}

.copilot-brand {
 display: flex;
 align-items: center;
 gap: 12px;
}

.copilot-logo {
 width: 40px;
 height: 40px;
 border-radius: 12px;
 background: linear-gradient(135deg, #8b5cf6, #6366f1);
 display: flex;
 align-items: center;
 justify-content: center;
}

.copilot-logo svg {
 width: 22px;
 height: 22px;
 fill: #fff;
}

.copilot-title {
 font-size: 16px;
 font-weight: 700;
 color: #f0f2f5;
 line-height: 1.2;
}

.copilot-subtitle {
 font-size: 12px;
 color: rgba(255, 255, 255, 0.5);
 line-height: 1.2;
}

.copilot-status {
 display: flex;
 align-items: center;
 gap: 8px;
 font-size: 12px;
 color: rgba(255, 255, 255, 0.5);
}

.copilot-status-dot {
 width: 8px;
 height: 8px;
 border-radius: 50%;
 background: #10b981;
 animation: copilot-pulse 2s infinite;
}

@keyframes copilot-pulse {
 0%, 100% { opacity: 1; }
 50% { opacity: 0.5; }
}

/* --- Suggestions Bar --- */
.copilot-suggestions {
 padding: 12px 24px;
 background: rgba(15, 20, 30, 0.6);
 border-bottom: 1px solid rgba(255, 255, 255, 0.04);
 overflow-x: auto;
 flex-shrink: 0;
}

.copilot-suggestions::-webkit-scrollbar {
 height: 0;
}

.copilot-suggestions-inner {
 display: flex;
 gap: 8px;
 white-space: nowrap;
}

.copilot-chip {
 padding: 8px 16px;
 border-radius: 20px;
 background: rgba(99, 102, 241, 0.08);
 border: 1px solid rgba(99, 102, 241, 0.2);
 color: #a5b4fc;
 font-size: 13px;
 cursor: pointer;
 transition: all 0.2s ease;
 font-family: inherit;
 white-space: nowrap;
}

.copilot-chip:hover:not(:disabled) {
 background: rgba(99, 102, 241, 0.18);
 border-color: rgba(99, 102, 241, 0.4);
 transform: translateY(-1px);
}

.copilot-chip:disabled {
 opacity: 0.5;
 cursor: not-allowed;
}

/* --- Conversation --- */
.copilot-conversation {
 flex: 1;
 overflow-y: auto;
 padding: 24px;
 display: flex;
 flex-direction: column;
 gap: 20px;
}

.copilot-conversation::-webkit-scrollbar {
 width: 6px;
}

.copilot-conversation::-webkit-scrollbar-track {
 background: transparent;
}

.copilot-conversation::-webkit-scrollbar-thumb {
 background: rgba(255, 255, 255, 0.1);
 border-radius: 3px;
}

/* --- Welcome State --- */
.copilot-welcome {
 display: flex;
 flex-direction: column;
 align-items: center;
 justify-content: center;
 text-align: center;
 padding: 60px 24px;
 opacity: 0.7;
}

.copilot-welcome-icon {
 width: 64px;
 height: 64px;
 border-radius: 20px;
 background: linear-gradient(135deg, #8b5cf6, #6366f1);
 display: flex;
 align-items: center;
 justify-content: center;
 margin-bottom: 20px;
}

.copilot-welcome-icon svg {
 width: 32px;
 height: 32px;
 fill: #fff;
}

.copilot-welcome h2 {
 font-size: 20px;
 font-weight: 600;
 color: #e4e8f0;
 margin-bottom: 8px;
}

.copilot-welcome p {
 font-size: 14px;
 color: rgba(255, 255, 255, 0.5);
 max-width: 480px;
}

/* --- Message Layout --- */
.copilot-message {
 display: flex;
 align-items: flex-start;
 gap: 12px;
 animation: copilot-msg-in 0.3s ease;
}

@keyframes copilot-msg-in {
 from { opacity: 0; transform: translateY(8px); }
 to { opacity: 1; transform: translateY(0); }
}

.copilot-message--user {
 flex-direction: row-reverse;
}

.copilot-message-avatar {
 width: 36px;
 height: 36px;
 border-radius: 12px;
 background: linear-gradient(135deg, #8b5cf6, #6366f1);
 display: flex;
 align-items: center;
 justify-content: center;
 flex-shrink: 0;
 font-size: 11px;
 font-weight: 700;
 color: #fff;
}

.copilot-message-avatar svg {
 width: 18px;
 height: 18px;
 fill: #fff;
}

.copilot-message--user .copilot-message-avatar {
 background: rgba(99, 102, 241, 0.2);
 color: #a5b4fc;
}

.copilot-message-content {
 max-width: 80%;
 min-width: 0;
}

.copilot-user-bubble {
 padding: 12px 16px;
 border-radius: 16px;
 border-top-right-radius: 4px;
 background: linear-gradient(135deg, #6366f1, #7c3aed);
 color: #fff;
 font-size: 14px;
 line-height: 1.5;
}

/* --- AI Response --- */
.copilot-response {
 display: flex;
 flex-direction: column;
 gap: 12px;
}

.copilot-response-summary {
 font-size: 14px;
 line-height: 1.6;
 color: #e4e8f0;
 padding: 14px 18px;
 background: rgba(30, 36, 50, 0.7);
 border: 1px solid rgba(255, 255, 255, 0.06);
 border-radius: 16px;
 border-top-left-radius: 4px;
}

/* --- Details Reveal (fade in after streaming) --- */
.copilot-details-reveal {
 display: flex;
 flex-direction: column;
 gap: 12px;
 animation: copilot-reveal 0.5s ease forwards;
}

@keyframes copilot-reveal {
 from { opacity: 0; transform: translateY(8px); }
 to { opacity: 1; transform: translateY(0); }
}

/* --- Section Cards --- */
.copilot-section {
 padding: 14px 18px;
 border-radius: 12px;
 background: rgba(20, 25, 40, 0.6);
 border: 1px solid rgba(255, 255, 255, 0.06);
}

.copilot-section--critical {
 border-left: 3px solid #ef4444;
}

.copilot-section--warning {
 border-left: 3px solid #f59e0b;
}

.copilot-section--info {
 border-left: 3px solid #6366f1;
}

.copilot-section--positive {
 border-left: 3px solid #10b981;
}

.copilot-section-header {
 display: flex;
 align-items: center;
 justify-content: space-between;
 margin-bottom: 10px;
}

.copilot-section-title {
 font-size: 13px;
 font-weight: 600;
 color: #f0f2f5;
}

.copilot-badge {
 font-size: 11px;
 font-weight: 600;
 padding: 3px 8px;
 border-radius: 10px;
}

.copilot-badge--critical {
 background: rgba(239, 68, 68, 0.15);
 color: #fca5a5;
}

.copilot-badge--warning {
 background: rgba(245, 158, 11, 0.15);
 color: #fcd34d;
}

.copilot-badge--info {
 background: rgba(99, 102, 241, 0.15);
 color: #a5b4fc;
}

.copilot-badge--positive {
 background: rgba(16, 185, 129, 0.15);
 color: #6ee7b7;
}

/* --- Bullets --- */
.copilot-bullets {
 list-style: none;
 padding: 0;
 margin: 0;
 display: flex;
 flex-direction: column;
 gap: 6px;
}

.copilot-bullet {
 font-size: 13px;
 color: rgba(255, 255, 255, 0.7);
 line-height: 1.5;
 padding-left: 16px;
 position: relative;
}

.copilot-bullet::before {
 content: "•";
 position: absolute;
 left: 0;
 color: rgba(255, 255, 255, 0.3);
}

/* --- Metrics --- */
.copilot-metrics {
 display: grid;
 grid-template-columns: repeat(auto-fit, minmax(120px, 1fr));
 gap: 10px;
}

.copilot-metric {
 padding: 10px 12px;
 border-radius: 8px;
 background: rgba(15, 20, 30, 0.5);
 border: 1px solid rgba(255, 255, 255, 0.04);
 display: flex;
 flex-direction: column;
 gap: 4px;
}

.copilot-metric-label {
 font-size: 11px;
 color: rgba(255, 255, 255, 0.5);
 text-transform: uppercase;
 letter-spacing: 0.5px;
}

.copilot-metric-value {
 font-size: 16px;
 font-weight: 700;
 color: #f0f2f5;
 display: flex;
 align-items: center;
 gap: 6px;
}

.copilot-trend-icon {
 font-size: 10px;
}

.copilot-trend--up {
 color: #ef4444;
}

.copilot-trend--down {
 color: #ef4444;
}

/* --- Action Card --- */
.copilot-action-card {
 padding: 16px 18px;
 border-radius: 12px;
 background: rgba(99, 102, 241, 0.06);
 border: 1px solid rgba(99, 102, 241, 0.2);
}

.copilot-action-header {
 display: flex;
 align-items: center;
 gap: 8px;
 margin-bottom: 10px;
}

.copilot-action-icon {
 width: 24px;
 height: 24px;
 border-radius: 6px;
 background: rgba(99, 102, 241, 0.2);
 display: flex;
 align-items: center;
 justify-content: center;
}

.copilot-action-icon svg {
 width: 14px;
 height: 14px;
 fill: #a5b4fc;
}

.copilot-action-label {
 font-size: 11px;
 font-weight: 600;
 color: #a5b4fc;
 text-transform: uppercase;
 letter-spacing: 0.5px;
}

.copilot-action-title {
 font-size: 14px;
 font-weight: 600;
 color: #f0f2f5;
 margin-bottom: 6px;
}

.copilot-action-description {
 font-size: 13px;
 color: rgba(255, 255, 255, 0.6);
 line-height: 1.5;
 margin-bottom: 10px;
}

.copilot-action-priority {
 font-size: 11px;
 font-weight: 600;
 padding: 3px 10px;
 border-radius: 10px;
 text-transform: capitalize;
}

.copilot-action-priority--high {
 background: rgba(239, 68, 68, 0.12);
 color: #fca5a5;
}

.copilot-action-priority--medium {
 background: rgba(245, 158, 11, 0.12);
 color: #fcd34d;
}

.copilot-action-priority--low {
 background: rgba(99, 102, 241, 0.12);
 color: #a5b4fc;
}

/* --- Timestamp --- */
.copilot-timestamp {
 font-size: 11px;
 color: rgba(255, 255, 255, 0.3);
 text-align: right;
 padding-top: 4px;
}

/* --- Typing Indicator --- */
.copilot-typing {
 display: flex;
 align-items: center;
 gap: 12px;
 padding: 8px 0;
 animation: copilot-msg-in 0.3s ease;
}

.copilot-typing-dots {
 display: flex;
 gap: 4px;
}

.copilot-typing-dot {
 width: 8px;
 height: 8px;
 border-radius: 50%;
 background: rgba(139, 92, 246, 0.6);
 animation: copilot-bounce 1.4s infinite ease-in-out;
}

.copilot-typing-dot:nth-child(1) { animation-delay: 0s; }
.copilot-typing-dot:nth-child(2) { animation-delay: 0.2s; }
.copilot-typing-dot:nth-child(3) { animation-delay: 0.4s; }

@keyframes copilot-bounce {
 0%, 80%, 100% { transform: scale(0.6); opacity: 0.4; }
 40% { transform: scale(1); opacity: 1; }
}

.copilot-typing-text {
 font-size: 12px;
 color: rgba(255, 255, 255, 0.4);
 font-style: italic;
}

/* --- Input Bar --- */
.copilot-input-bar {
 padding: 16px 24px;
 background: rgba(15, 20, 30, 0.95);
 border-top: 1px solid rgba(255, 255, 255, 0.06);
 flex-shrink: 0;
}

.copilot-input-container {
 display: flex;
 align-items: center;
 gap: 8px;
 background: rgba(20, 25, 40, 0.8);
 border: 1px solid rgba(255, 255, 255, 0.08);
 border-radius: 24px;
 padding: 4px 4px 4px 16px;
 transition: border-color 0.2s;
}

.copilot-input-container:focus-within {
 border-color: rgba(99, 102, 241, 0.5);
}

.copilot-input {
 flex: 1;
 background: none;
 border: none;
 outline: none;
 color: #e4e8f0;
 font-size: 14px;
 font-family: inherit;
 padding: 8px 0;
}

.copilot-input::placeholder {
 color: rgba(255, 255, 255, 0.3);
}

.copilot-send-btn {
 width: 36px;
 height: 36px;
 border-radius: 50%;
 background: linear-gradient(135deg, #8b5cf6, #6366f1);
 border: none;
 display: flex;
 align-items: center;
 justify-content: center;
 cursor: pointer;
 transition: all 0.2s ease;
 flex-shrink: 0;
}

.copilot-send-btn svg {
 width: 16px;
 height: 16px;
 fill: #fff;
}

.copilot-send-btn:hover:not(:disabled) {
 transform: scale(1.05);
 box-shadow: 0 4px 12px rgba(139, 92, 246, 0.4);
}

.copilot-send-btn:disabled {
 opacity: 0.4;
 cursor: not-allowed;
}
","export default function insertStyle(css, tagName = "style") {
 if (!css || typeof window === "undefined")
 return;
 if (tagName === "style") {
 const style = document.createElement("style");
 style.setAttribute("type", "text/css");
 style.innerHTML = css;
 document.head.appendChild(style);
 }
 else if (tagName === "link") {
 const link = document.createElement("link");
 link.setAttribute("rel", "stylesheet");
 link.setAttribute("href", css);
 document.head.appendChild(link);
 }
 return css;
}","import React, { useState, useRef, useEffect } from "react";
import "./copilot.css";
import {
 getResponse,
 CopilotResponse,
 ResponseSection,
 MetricItem,
 RecommendedAction,
} from "./responseProvider";
import { useStreamingText } from "../shared/useStreamingText";

interface Message {
 id: string;
 type: "user" | "ai";
 text?: string;
 response?: CopilotResponse;
}

const SUGGESTED_QUESTIONS = [
 "Why did Store 104's PulseScore drop?",
 "Which stores need immediate attention?",
 "Summarize today's operations.",
 "Show all equipment failures.",
 "Show delivery partner incidents.",
 "Show refund statistics.",
 "Show fraud alerts.",
 "What should Operations focus on today?",
];

function AIIcon() {
 return (
 <svg viewBox="0 0 24 24">
 <path d="M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm-1 17.93c-3.95-.49-7-3.85-7-7.93 0-.62.08-1.21.21-1.79L9 15v1c0 1.1.9 2 2 2v1.93zm6.9-2.54c-.26-.81-1-1.39-1.9-1.39h-1v-3c0-.55-.45-1-1-1H8v-2h2c.55 0 1-.45 1-1V7h2c1.1 0 2-.9 2-2v-.41c2.93 1.19 5 4.06 5 7.41 0 2.08-.8 3.97-2.1 5.39z" />
 </svg>
 );
}

function SendIcon() {
 return (
 <svg viewBox="0 0 24 24">
 <path d="M2.01 21L23 12 2.01 3 2 10l15 2-15 2z" />
 </svg>
 );
}

function ActionIcon() {
 return (
 <svg viewBox="0 0 24 24">
 <path d="M9 11H7v2h2v-2zm4 0h-2v2h2v-2zm4 0h-2v2h2v-2zm2-7h-1V2h-2v2H8V2H6v2H5c-1.11 0-1.99.9-1.99 2L3 20c0 1.1.89 2 2 2h14c1.1 0 2-.9 2-2V6c0-1.1-.9-2-2-2zm0 16H5V9h14v11z" />
 </svg>
 );
}

function TrendArrow({ trend }: { trend?: "up" | "down" | "neutral" }) {
 if (trend === "up") return <span className="copilot-trend-icon copilot-trend--up">▲</span>;
 if (trend === "down") return <span className="copilot-trend-icon copilot-trend--down">▼</span>;
 return null;
}

function SectionCard({ section }: { section: ResponseSection; key?: React.Key }) {
 const sev = section.severity || "info";
 return (
 <div className={`copilot-section copilot-section--${sev}`}>
 <div className="copilot-section-header">
 <span className="copilot-section-title">{section.title}</span>
 {section.badge && (
 <span className={`copilot-badge copilot-badge--${sev}`}>{section.badge}</span>
 )}
 </div>
 {section.bullets && (
 <ul className="copilot-bullets">
 {section.bullets.map((b, i) => (
 <li key={i} className="copilot-bullet">{b}</li>
 ))}
 </ul>
 )}
 {section.metrics && (
 <div className="copilot-metrics">
 {section.metrics.map((m, i) => (
 <MetricCard key={i} metric={m} />
 ))}
 </div>
 )}
 </div>
 );
}

function MetricCard({ metric }: { metric: MetricItem; key?: React.Key }) {
 return (
 <div className="copilot-metric">
 <span className="copilot-metric-label">{metric.label}</span>
 <span className="copilot-metric-value">
 {metric.value}
 <TrendArrow trend={metric.trend} />
 </span>
 </div>
 );
}

function ActionCard({ action }: { action: RecommendedAction }) {
 return (
 <div className="copilot-action-card">
 <div className="copilot-action-header">
 <div className="copilot-action-icon"><ActionIcon /></div>
 <span className="copilot-action-label">Recommended Action</span>
 </div>
 <div className="copilot-action-title">{action.title}</div>
 <div className="copilot-action-description">{action.description}</div>
 <span className={`copilot-action-priority copilot-action-priority--${action.priority}`}>
 {action.priority} priority
 </span>
 </div>
 );
}

/**
 * StreamingAIResponse — Streams the summary text word-by-word,
 * then reveals sections and action card after streaming completes.
 */
function StreamingAIResponse({ response, isLatest }: { response: CopilotResponse; isLatest: boolean }) {
 const shouldStream = isLatest;
 const { displayText, isComplete } = useStreamingText(response.summary, shouldStream, 40);

 const summaryToShow = shouldStream ? displayText : response.summary;
 const showDetails = !shouldStream || isComplete;

 return (
 <div className="copilot-response">
 <div className="copilot-response-summary">{summaryToShow}</div>
 {showDetails && (
 <div className="copilot-details-reveal">
 {response.sections.map((sec, i) => (
 <SectionCard key={i} section={sec} />
 ))}
 <ActionCard action={response.recommendedAction} />
 <div className="copilot-timestamp">{response.timestamp}</div>
 </div>
 )}
 </div>
 );
}

function TypingIndicator() {
 return (
 <div className="copilot-typing">
 <div className="copilot-message-avatar" style={{ background: "linear-gradient(135deg, #8b5cf6, #6366f1)" }}>
 <AIIcon />
 </div>
 <div className="copilot-typing-dots">
 <div className="copilot-typing-dot" />
 <div className="copilot-typing-dot" />
 <div className="copilot-typing-dot" />
 </div>
 <span className="copilot-typing-text">Analyzing operations data...</span>
 </div>
 );
}

export default function CopilotApp() {
 const [messages, setMessages] = useState<Message[]>([]);
 const [input, setInput] = useState("");
 const [isLoading, setIsLoading] = useState(false);
 const [latestAiId, setLatestAiId] = useState<string | null>(null);
 const conversationRef = useRef<HTMLDivElement>(null);
 const inputRef = useRef<HTMLInputElement>(null);

 useEffect(() => {
 if (conversationRef.current) {
 conversationRef.current.scrollTop = conversationRef.current.scrollHeight;
 }
 }, [messages, isLoading]);

 const sendMessage = async (text: string) => {
 if (!text.trim() || isLoading) return;
 const userMsg: Message = { id: Date.now().toString(), type: "user", text: text.trim() };
 setMessages((prev) => [...prev, userMsg]);
 setInput("");
 setIsLoading(true);
 try {
 const response = await getResponse(text.trim());
 const aiId = (Date.now() + 1).toString();
 const aiMsg: Message = { id: aiId, type: "ai", response };
 setMessages((prev) => [...prev, aiMsg]);
 setLatestAiId(aiId);
 } finally {
 setIsLoading(false);
 inputRef.current?.focus();
 }
 };

 const handleSubmit = (e: React.FormEvent) => { e.preventDefault(); sendMessage(input); };
 const handleChipClick = (question: string) => { sendMessage(question); };
 const handleKeyDown = (e: React.KeyboardEvent) => { if (e.key === "Enter" && !e.shiftKey) { e.preventDefault(); sendMessage(input); } };

 return (
 <div className="copilot-page">
 <header className="copilot-header">
 <div className="copilot-brand">
 <div className="copilot-logo"><AIIcon /></div>
 <div>
 <div className="copilot-title">DarkOps AI</div>
 <div className="copilot-subtitle">Operations Copilot</div>
 </div>
 </div>
 <div className="copilot-status">
 <div className="copilot-status-dot" />
 Online — 52 stores monitored
 </div>
 </header>
 <div className="copilot-suggestions">
 <div className="copilot-suggestions-inner">
 {SUGGESTED_QUESTIONS.map((q, i) => (
 <button key={i} className="copilot-chip" onClick={() => handleChipClick(q)} disabled={isLoading}>{q}</button>
 ))}
 </div>
 </div>
 <div className="copilot-conversation" ref={conversationRef}>
 {messages.length === 0 && !isLoading && (
 <div className="copilot-welcome">
 <div className="copilot-welcome-icon"><AIIcon /></div>
 <h2>DarkOps Operations Intelligence</h2>
 <p>Ask me about store health, equipment status, delivery partners, fraud alerts, refund analytics, or operational priorities.</p>
 </div>
 )}
 {messages.map((msg) => {
 if (msg.type === "user") {
 return (
 <div key={msg.id} className="copilot-message copilot-message--user">
 <div className="copilot-message-avatar">You</div>
 <div className="copilot-message-content"><div className="copilot-user-bubble">{msg.text}</div></div>
 </div>
 );
 }
 return (
 <div key={msg.id} className="copilot-message copilot-message--ai">
 <div className="copilot-message-avatar"><AIIcon /></div>
 <div className="copilot-message-content">
 {msg.response && (
 <StreamingAIResponse
 response={msg.response}
 isLatest={msg.id === latestAiId}
 />
 )}
 </div>
 </div>
 );
 })}
 {isLoading && <TypingIndicator />}
 </div>
 <form className="copilot-input-bar" onSubmit={handleSubmit}>
 <div className="copilot-input-container">
 <input ref={inputRef} className="copilot-input" type="text" placeholder="Ask about operations, store health, incidents..." value={input} onChange={(e) => setInput(e.target.value)} onKeyDown={handleKeyDown} disabled={isLoading} autoFocus />
 <button type="submit" className="copilot-send-btn" disabled={!input.trim() || isLoading}><SendIcon /></button>
 </div>
 </form>
 </div>
 );
}
","/**
 * useStreamingText — Shared React hook that streams text word-by-word.
 * Provides a typewriter effect for AI responses.
 */

import { useState, useEffect, useRef } from 'react';

interface StreamingTextResult {
 displayText: string;
 isStreaming: boolean;
 isComplete: boolean;
}

/**
 * Streams text word-by-word at a natural pace.
 * @param fullText - The complete text to stream
 * @param enabled - Whether streaming should begin (default true)
 * @param baseInterval - Base ms per word (default 45)
 */
export function useStreamingText(
 fullText: string,
 enabled: boolean = true,
 baseInterval: number = 45
): StreamingTextResult {
 const [wordIndex, setWordIndex] = useState(0);
 const [isComplete, setIsComplete] = useState(false);
 const wordsRef = useRef<string[]>([]);
 const timerRef = useRef<ReturnType<typeof setTimeout> | null>(null);

 // Split text into words preserving whitespace/newlines
 useEffect(() => {
 if (!fullText || !enabled) {
 wordsRef.current = [];
 setWordIndex(0);
 setIsComplete(!fullText);
 return;
 }

 // Split on whitespace but keep newlines as separate tokens
 const tokens = fullText.split(/(\s+)/);
 wordsRef.current = tokens.filter((t) => t.length > 0);
 setWordIndex(0);
 setIsComplete(false);
 }, [fullText, enabled]);

 // Stream words one by one
 useEffect(() => {
 if (!enabled || isComplete || wordsRef.current.length === 0) return;

 const totalWords = wordsRef.current.filter((t) => t.trim().length > 0).length;

 // Adjust speed based on response length:
 // Shorter responses (< 20 words) slightly faster
 // Longer responses (> 80 words) slightly faster to not drag
 let interval = baseInterval;
 if (totalWords < 20) {
 interval = baseInterval * 0.8;
 } else if (totalWords > 80) {
 interval = baseInterval * 0.7;
 }

 const advance = () => {
 setWordIndex((prev) => {
 const next = prev + 1;
 if (next >= wordsRef.current.length) {
 setIsComplete(true);
 return prev;
 }
 return next;
 });
 };

 // Add slight randomness for natural feel (+/- 15ms)
 const jitter = Math.random() * 30 - 15;
 const delay = Math.max(15, interval + jitter);

 timerRef.current = setTimeout(advance, delay);

 return () => {
 if (timerRef.current) {
 clearTimeout(timerRef.current);
 }
 };
 }, [wordIndex, enabled, isComplete, baseInterval]);

 // Build display text from words up to current index
 const displayText =
 wordsRef.current.length > 0
 ? wordsRef.current.slice(0, wordIndex + 1).join('')
 : '';

 const isStreaming = enabled && !isComplete && wordsRef.current.length > 0;

 return { displayText, isStreaming, isComplete };
}
